void themcuoi(node **head, int x){
    node *newNode = (node*)malloc(sizeof(node));
    newNode->data = x;
    newNode->next = newNode->prev = NULL;
    if(*head == NULL){ *head = newNode; return; }  // DSLK rong
    node *tmp = *head;
    while(tmp->next != NULL)
        tmp = tmp->next;              // toi node cuoi
    tmp->next = newNode;
    newNode->prev = tmp;
}
